// The History Clock watch face: Watch Face Format, resources only (no code).
// res/raw/watchface.xml is generated by clock/tools/make_watchface.py: edit the generator, not the XML.
plugins {
    alias(libs.plugins.android.application)
}

android {
    enableKotlin = false
    namespace = "com.timetravelco.historyclock.watchface"
    compileSdk = 36

    defaultConfig {
        applicationId = "com.timetravelco.historyclock.watchface"
        minSdk = 33
        targetSdk = 36
        versionCode = 3
        versionName = "0.3.0"
    }

    // A fixed development key, so every cloud build can update the face already on the watch
    // (otherwise each build gets a new random debug key and the watch refuses the update).
    // Development only: a Play release will be signed with a separate, private key.
    signingConfigs {
        create("dev") {
            storeFile = file("../keystore/dev.jks")
            storePassword = "historyclock"
            keyAlias = "dev"
            keyPassword = "historyclock"
        }
    }

    buildTypes {
        debug {
            signingConfig = signingConfigs.getByName("dev")
            isMinifyEnabled = true
        }
        release {
            isMinifyEnabled = true
            // Keep resources: the watch face is nothing but resources.
            isShrinkResources = false
            signingConfig = signingConfigs.getByName("dev")
        }
    }
}
